  glance: ['At a glance', 'Every vector, one screen', 'Business development at a glance.', 'Activity, response and commercial progress — with the age of each source in view.', '<path d="M3 4h18v16H3zM3 10h18M9 4v16M15 4v16"/>'],
  overview: ['Overview', 'The operating picture', 'Business development,<br>in perspective.', 'Activity and commercial outcomes, together in one place.', '<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>'],
  ads: ['LinkedIn Ads', 'Paid acquisition', 'From attention<br>to qualified demand.', 'Campaign economics, lead quality, and the evidence behind them.', '<path d="M4 19V12M10 19V5M16 19V9M22 19H2"/>'],
  waalaxy: ['Waalaxy', 'LinkedIn automation', 'Outreach, with<br>context.', 'Charles’s automation activity, responses, and campaign coverage.', '<path d="M21 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 18-3"/><path d="M7 9h8M7 13h5"/>'],
  content: ['LinkedIn Content', 'Organic & boosted content', 'Content that starts<br>conversations.', 'Charles’s profile and the Centripetal company page.', '<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M8 8h8M8 12h8M8 16h5"/>'],
  crm: ['Pipedrive', 'Commercial progress', 'Relationships into<br>opportunities.', 'New records, activity, pipeline positions, and follow-through.', '<path d="M3 5h18v4l-7 6v6l-4-2v-4L3 9z"/>'],
  video: ['Video DMs', 'Personal outreach', 'Personal outreach,<br>accounted for.', 'The Video DM workbook, with status and delivery kept distinct.', '<rect x="3" y="6" width="12" height="13" rx="1"/><path d="m15 10 6-4v13l-6-4z"/>'],
  referrals: ['Referrals', 'Relationship-led growth', 'Introductions into<br>new relationships.', 'Referral activity, qualified introductions and commercial outcomes.', '<circle cx="6" cy="6" r="3"/><circle cx="18" cy="6" r="3"/><circle cx="12" cy="19" r="3"/><path d="m7 9 4 7m6-7-4 7M9 6h6"/>'],
